@vom 1
@view 1602x842
@layers 2 focus=L1
L1 modal cover=100%
  dialog "项目记忆"
    sectionheader "项目记忆"
      heading "项目记忆"
      @e101 button "关闭此对话框"
    paragraph "查看已发布记忆、审核提取候选，或发起一次新的项目记忆提取。"
    @e102 tab "已发布记忆" [selected]
      [§ active: 已发布记忆]
        ACTIVE 记忆会参与后续 Agent 召回。
        还没有已发布记忆
        从候选批准，或运行一次记忆提取任务。
        刷新
    @e103 tab "待审候选" [unselected]
    @e104 tab "提取任务" [unselected]
    tabpanel "已发布记忆"
      StaticText "ACTIVE 记忆会参与后续 Agent 召回。"
      @e105 button "刷新"
      paragraph "还没有已发布记忆"
      paragraph "从候选批准，或运行一次记忆提取任务。"
